L["Hello, %s"] = "Merhaba, %s"
L["Welcome to Polestar"] = "Polestar'a hoş geldin"
L["Polestar guides you step by step: who to talk to, what to kill or collect, and where to go."] = "Polestar sana adım adım yol gösterir: kiminle konuşacağını, neyi öldürüp toplayacağını ve nereye gideceğini."
L["Accept and turn in guide quests for me"] = "Rehber görevlerini benim için al ve teslim et"
L["Only quests in the next steps of your open guides. Never picks between rewards. Hold Shift to skip."] = "Yalnızca açık rehberlerinin sıradaki adımlarındaki görevler. Ödüller arasında asla seçim yapmaz. Atlamak için Shift'e basılı tut."
L["Load a guide for me when I log in"] = "Girişte benim için bir rehber yükle"
L["Our routes are still in beta"] = "Rotalarımız hâlâ beta aşamasında"
L["Join us on Discord"] = "Discord'da bize katıl"
L["Choose your first guide"] = "İlk rehberini seç"
L["Polestar has no guide to suggest for where you are."] = "Polestar'ın bulunduğun yer için önerebileceği bir rehber yok."
-- L["Beta"] = ""
L["Back"] = "Geri"
L["Pages"] = "Sayfalar"
L["The shortest walk. Cuts across fields and goes straight over hills."] = "En kısa yürüyüş. Tarlaların içinden kestirir, tepelerin üstünden dümdüz geçer."
L["Takes roads when they aren't much longer, and goes round steep hills."] = "Çok uzun değilse yolları kullanır, dik tepelerin çevresinden dolaşır."
L["Stays on roads, even when it's longer. Slower, but easy to follow."] = "Daha uzun olsa da yollardan ayrılmaz. Daha yavaş ama izlemesi kolay."
L["Supplies"] = "Malzemeler"
L["your next stop"] = "sıradaki durağın"
L["Points the way. The map marks each place."] = "Yolu gösterir. Harita her yeri işaretler."
L["%s opens the guide window on the right. The arrow points at your first stop."] = "%s, sağda rehber penceresini açar. Ok ilk durağını gösterir."
L["Played to the end in tests, but not yet by players. If a step is wrong, press %s in the guide window and tell us on Discord."] = "Testlerde sonuna kadar oynandı, ama henüz oyuncular oynamadı. Bir adım yanlışsa rehber penceresinde %s düğmesine bas ve Discord'da bize söyle."
L["Feedback, bug reports and news."] = "Geri bildirim, hata bildirimleri ve haberler."
L["Guides by other players, installed like any addon. They show under Community guides in the guide list."] = "Başka oyuncuların rehberleri, her eklenti gibi kurulur. Rehber listesinde Topluluk rehberleri altında görünürler."
L["Route line"] = "Rota çizgisi"
L["Mark what the target button finds"] = "Hedef düğmesinin bulduğunu işaretle"
L["A skull on the enemy, a star on the friendly NPC. In a group it never takes another player's icon."] = "Düşmana kafatası, dost NPC'ye yıldız. Grupta asla başka bir oyuncunun simgesini almaz."
L["Ping it for my group"] = "Grubum için işaret ver"
L["Your group sees what the target button and the step key found, even behind rocks and buildings."] = "Grubun, hedef düğmesinin ve adım tuşunun bulduğunu kayaların ve binaların arkasında bile görür."
L["The next pages set Polestar up for how you play. Each choice works at once, and Skip install keeps everything as it is."] = "Sonraki sayfalar Polestar'ı oynayışına göre kurar. Her seçim hemen işler. Kurulumu atla her şeyi olduğu gibi bırakır."
L["Your settings come with you from your other characters. Next, the choice that is this character's own."] = "Ayarların diğer karakterlerinden seninle gelir. Sırada bu karaktere özel seçim var."
L["Your settings come with you from your other characters."] = "Ayarların diğer karakterlerinden seninle gelir."
L["Skip install keeps these as they are."] = "Kurulumu atla, bunları olduğu gibi bırakır."
L["How the way to your goal shows on the world map and the minimap."] = "Hedefine giden yolun dünya haritasında ve mini haritada nasıl göründüğü."
L["How Polestar helps with your quests."] = "Polestar'ın görevlerinde sana nasıl yardım ettiği."
L["Gear advice scores quest rewards with them: it names the one to take and marks upgrades. Automatic follows your talents."] = "Ekipman önerisi görev ödüllerini bunlarla puanlar: alınacak olanı söyler ve yükseltmeleri işaretler. Otomatik, yeteneklerini izler."
L["Leveling guides can take you through dungeons and group quests on your way. Choose how much of that you want."] = "Seviye rehberleri yolda seni zindanlardan ve grup görevlerinden geçirebilir. Bunun ne kadarını istediğini seç."
L["Dungeons in my route"] = "Rotamdaki zindanlar"
L["For a group of five: the guide picks up a dungeon's quests on its way, sends you to the door at the right level and hands them in after."] = "Beş kişilik bir grup için: rehber yolda bir zindanın görevlerini alır, seni doğru seviyede kapıya gönderir, sonra da görevleri teslim eder."
L["The solo route."] = "Tek başına rota."
L["The guide asks at each dungeon."] = "Rehber her zindanda sorar."
L["Run them"] = "Hepsini yap"
L["Every dungeon on your way."] = "Yolundaki her zindan."
L["The guide asks when you reach one."] = "Rehber birine varınca sorar."
L["Solo: the route leaves them out."] = "Tek başına: rota onları dışarıda bırakır."
L["Your route"] = "Rotan"
L["How the arrow walks you, and how the way shows on your maps."] = "Okun seni nasıl yürüttüğü ve yolun haritalarında nasıl göründüğü."
L["Every style keeps you out of enemy towns and zones far above your level."] = "Her stil seni düşman kasabalarından ve seviyenin çok üstündeki bölgelerden uzak tutar."
L["Polestar's own: a night sky, gold accents."] = "Polestar'ın kendisi: gece göğü, altın vurgular."
L["No frame, a soft dark veil."] = "Çerçeve yok, yumuşak koyu bir tül."
L["An inn by the fire: warm wood, ember light, parchment text."] = "Ateş başında bir han: sıcak ahşap, kor ışığı, parşömen yazı."
L["Forever's own art: bronze metal frames."] = "Forever'ın kendi çizimi: bronz metal çerçeveler."
L["The game's frames in their modern art."] = "Oyunun çerçeveleri, modern çizimleriyle."
L["The original game's frames."] = "Orijinal oyunun çerçeveleri."
L["Your look"] = "Görünümün"
L["Every Polestar window wears it, this one too. Colours, fonts and each look's versions are in Settings, Theme."] = "Her Polestar penceresi bunu giyer, bu da. Renkler, yazı tipleri ve her görünümün sürümleri Ayarlar'da, Tema altında."
L["You're all set"] = "Hazırsın"
L["Change it later"] = "Sonra değiştir"
L["Help improve the routes"] = "Rotaların iyileşmesine yardım et"
L["Your guide is open in the guide window on the right. The arrow points at your next stop."] = "Rehberin sağdaki rehber penceresinde açık. Ok sonraki durağını gösteriyor."
L["Everything you chose works already, with no reload."] = "Seçtiğin her şey yeniden yükleme gerekmeden şimdiden çalışıyor."
L["Every choice here is in Settings, and its search finds any setting by name. Install opens again from there, or with %s."] = "Buradaki her seçim Ayarlar'da. Araması her ayarı adıyla bulur. Kurulum oradan ya da %s ile yeniden açılır."
L["The Polestar Recorder, an optional addon of its own, records your play without names so the routes get better. Its page in Settings says how it works."] = "Kendi başına isteğe bağlı bir eklenti olan Polestar Recorder, rotalar iyileşsin diye oyununu isimler olmadan kaydeder. Ayarlar'daki sayfası nasıl çalıştığını anlatır."
L["Skip install"] = "Kurulumu atla"
L["Keeps every setting as it is. Install opens again from Settings, or with /polestar install."] = "Her ayarı olduğu gibi bırakır. Kurulum Ayarlar'dan ya da /polestar install ile yeniden açılır."
L["Finish"] = "Bitir"
L["Install  ·  Step %d of %d"] = "Kurulum  ·  Adım %d / %d"
L["Polestar Install"] = "Polestar Kurulumu"
L["Show a button that targets the step's mobs and NPCs"] = "Adımın yaratıklarını ve NPC'lerini hedef alan bir düğme göster"
L["Their name beside the button: green for an NPC, red for a mob, gold for an elite or rare."] = "Adları düğmenin yanında: NPC için yeşil, yaratık için kırmızı, elit ya da rare için altın."
L["Groups"] = "Gruplar"
L["Leveling guides mark some elite and escort quests for a group. Choose what the guide does at them."] = "Seviye rehberleri bazı elit ve eskort görevlerini grup için işaretler. Rehberin bunlarda ne yapacağını seç."
L["Simple target button"] = "Basit hedef düğmesi"
L["Embalming Ichor"] = "Embalming Ichor"
L["Off. The step key still targets the same names."] = "Kapalı. Adım tuşu yine aynı adları hedef alır."
L["Click it, or press %s: each press targets the next name."] = "Ona tıkla ya da %s tuşuna bas: her basış sıradaki adı hedef alır."
L["Click it: each click targets the next name."] = "Ona tıkla: her tık sıradaki adı hedef alır."
L["Click a name to target it, or press %s for the first one close by."] = "Hedef almak için bir ada tıkla ya da yakındaki ilki için %s tuşuna bas."
L["Click a name to target it."] = "Hedef almak için bir ada tıkla."
L["Target the mobs and NPCs of your step with one click."] = "Adımının yaratıklarını ve NPC'lerini tek tıkla hedef al."
L["Each name it can target is a row with the creature's face and the item it drops for the step."] = "Hedef alabileceği her ad, yaratığın yüzü ve adım için düşürdüğü eşyayla bir satırdır."
L["One square button instead of the list: each click targets the next name."] = "Liste yerine tek kare düğme: her tık sıradaki adı hedef alır."
L["No button? The key \"%s\" (Key Bindings, Polestar) targets the same names. Move frames, in Settings, moves the button."] = "Düğme yok mu? “%s” tuşu (Key Bindings, Polestar) aynı adları hedef alır. Ayarlar'daki Çerçeveleri taşı düğmeyi taşır."
L["Group quest"] = "Grup görevi"
L["In your route: the guide takes you to it. Bring a group."] = "Rotanda: rehber seni ona götürür. Bir grup getir."
L["Left out: the guide keeps to the solo route."] = "Dışarıda: rehber tek başına rotaya bağlı kalır."
L["When you reach one, the guide window asks."] = "Birine varınca rehber penceresi sorar."
L["The guide takes you to each one."] = "Rehber seni her birine götürür."
L["The guide leaves them out."] = "Rehber onları dışarıda bırakır."
L["For a party levelling together: every one is in the route."] = "Birlikte seviye atlayan bir grup için: hepsi rotada."
L["Point at a look to see it here; click it to wear it."] = "Burada görmek için bir görünümün üstüne gel, giymek için tıkla."
L["Built in"] = "Yerleşik"
L["Leaves out grey quests, and quests behind you that pay less than full XP when going back for them costs more time than they give. A quest still paying full XP stays, and so does one a later quest needs. The guide window says what it left out."] = "Gri görevleri ve geride kalıp tam XP'den az veren görevleri, onlara dönmek kazandırdığından çok zaman alıyorsa dışarıda bırakır. Hâlâ tam XP veren görev kalır, sonraki bir görevin gerektirdiği görev de. Neyi dışarıda bıraktığını rehber penceresi söyler."
L["More concept looks are in Settings, Theme."] = "Daha fazla konsept görünüm Ayarlar, Tema sayfasında."
L["Guide window layout"] = "Rehber penceresi düzeni"
L["How the guide window lays out the step. More in Settings, Guide window, Presets."] = "Rehber penceresinin adımı nasıl yerleştirdiği. Fazlası: Ayarlar, Rehber penceresi, Hazır ayarlar."
L["%s: /reload after picking it."] = "%s: seçtikten sonra /reload yap."
L["The step card, Up next under it."] = "Adım kartı, altında Sıradaki."
-- L["Alpha"] = ""
