L["Score items for your class and talents and point out upgrades."] = "Eşyaları sınıfına ve yeteneklerine göre puanlar ve yükseltmeleri gösterir."
L["Stat weights"] = "İstatistik ağırlıkları"
L["Which levelling weights score your items. Automatic follows the talent tree with the most points."] = "Eşyalarını hangi seviye atlama ağırlıklarının puanlayacağı. Otomatik, en çok puan verdiğin yetenek ağacını izler."
L["Tooltip comparison"] = "İpucunda karşılaştırma"
L["Show on item tooltips how much better or worse an item is than what you wear."] = "Eşya ipuçlarında bir eşyanın giydiğinden ne kadar iyi ya da kötü olduğunu göster."
L["Reward pick in the guide"] = "Rehberde ödül seçimi"
L["Under a turn-in step, name the reward to take: an upgrade with its gain, else the best one you can use. The marks on the game's reward panel are under Quest rewards."] = "Bir teslim adımının altında alınacak ödülü söyler: kazancıyla birlikte bir yükseltme, yoksa kullanabileceğin en iyisi. Oyunun ödül panelindeki işaretler Görev ödülleri altında."
L["Reward pick on tooltips"] = "İpuçlarında ödül seçimi"
L["On a quest reward's tooltip, say whether it is the upgrade to take."] = "Bir görev ödülünün ipucunda alınacak yükseltme olup olmadığını söyle."
L["Upgrade threshold"] = "Yükseltme eşiği"
L["Smaller gains than this are not called upgrades."] = "Bundan küçük kazançlara yükseltme denmez."
L["Pair with bag items"] = "Çanta eşyalarıyla eşleştir"
L["Against a worn two-hander, weigh a one-hander together with the best off-hand piece in your bags."] = "Giyili iki elli silaha karşı, tek elli bir silahı çantandaki en iyi ikinci el parçasıyla birlikte değerlendir."
L["Upgrade arrows in bags"] = "Çantada yükseltme okları"
L["A green arrow on each item in your bags that is an upgrade for your spec, in the game's bags and in Baganator."] = "Oyunun çantalarında ve Baganator'da, uzmanlığın için yükseltme olan her eşyanın üstünde yeşil bir ok."
L["Manage custom weights"] = "Özel ağırlıkları yönet"
L["Import a Pawn scale string, and use, rename, export or delete the scales you have."] = "Bir Pawn ölçek metni içe aktar, elindeki ölçekleri kullan, yeniden adlandır, dışa aktar ya da sil."
L["Leave bag arrows to Pawn"] = "Çanta oklarını Pawn'a bırak"
L["Pawn is installed and draws its own upgrade arrows in your bags. Turn this on to hide Polestar's, so an item does not carry two."] = "Pawn kurulu ve çantanda kendi yükseltme oklarını çiziyor. Polestar'ınkileri gizlemek için bunu aç, böylece bir eşyada iki ok olmaz."
L["Use Forever Leveling BiS when installed"] = "Yüklüyse Forever Leveling BiS'i kullan"
L["With Stat weights on Automatic, gear advice takes Forever Leveling BiS's gains, scores and spec from its version 1.2.9, and its upgrade arrows in your bags from the versions before."] = "İstatistik ağırlıkları Otomatik'teyken ekipman önerisi, 1.2.9 sürümünden itibaren Forever Leveling BiS'in kazançlarını, puanlarını ve uzmanlığını, önceki sürümlerden de çantalarındaki yükseltme oklarını alır."
L["Manage"] = "Yönet"
L["Adjust weights"] = "Ağırlıkları ayarla"
L["Weigh a stat more or less than Polestar does for your spec. Revert to default puts Polestar's weights back."] = "Bir istatistiği uzmanlığın için Polestar'dan daha çok ya da daha az tart. Varsayılana dön, Polestar'ın ağırlıklarını geri koyar."

