-- Dungeons/Attune.lua
L["Lets Lothos Riftwaker in Blackrock Mountain send you to the Molten Core; without it, walk in through Blackrock Depths."] = "Bununla Blackrock Mountain'daki Lothos Riftwaker seni Molten Core'a gönderir, olmadan Blackrock Depths üzerinden yürüyerek girersin."
L["Douses the Molten Core's runes; Majordomo Executus comes out only when every rune is doused. Duke Hydraxis hands it out once Hands of the Enemy is done."] = "Molten Core'un rünlerini söndürür. Majordomo Executus ancak tüm rünler sönünce ortaya çıkar. Duke Hydraxis, Hands of the Enemy görevi bitince bunu verir."
L["Everyone entering Onyxia's Lair carries the Drakefire Amulet."] = "Onyxia's Lair'e giren herkes Drakefire Amulet taşır."
L["Lets you touch the Orb of Command in Upper Blackrock Spire to reach Blackwing Lair; without it, walk in through the spire."] = "Bununla Blackwing Lair'e ulaşmak için Upper Blackrock Spire'daki Orb of Command'a dokunabilirsin, olmadan kulenin içinden yürüyerek girersin."
L["Everyone entering Naxxramas needs it; which of the three quests you take depends on your standing with the Argent Dawn."] = "Naxxramas'a giren herkese gerekir. Üç görevden hangisini alacağın Argent Dawn ile itibarına bağlı."
L["Opens Scholomance's gate; one key opens it for the group."] = "Scholomance'ın kapısını açar, bir anahtar grup için açar."
L["Opens the Shadowforge gates in Blackrock Depths; one key opens them for the group."] = "Blackrock Depths'teki Shadowforge kapılarını açar, bir anahtar grup için açar."
L["Opens the cells of Blackrock Depths' prison."] = "Blackrock Depths hapishanesinin hücrelerini açar."
L["Opens the Eastwall Gate into Stratholme's Scourge-held districts."] = "Stratholme'un Scourge elindeki mahallelerine açılan Eastwall Gate'i açar."
L["Opens the inner doors of Dire Maul's North and West wings."] = "Dire Maul'un North ve West kanatlarının iç kapılarını açar."
L["Opens Gnomeregan's back door, the Workshop entrance."] = "Gnomeregan'ın arka kapısını, Workshop girişini açar."
L["Opens the doors of the Armory and the Cathedral."] = "Armory ve Cathedral'ın kapılarını açar."
L["Rings the gong by the sacred pool in Zul'Farrak to call Gahz'rilla; one mallet does it for the group. Qiaga the Keeper (elite) on top of the Altar of Zul in the Hinterlands drops the Sacred Mallet: use it at the altar at the very top of Jintha'Alor and it becomes the Mallet of Zul'Farrak. Both places are full of elites."] = "Zul'Farrak'taki kutsal havuzun yanındaki gongu çalarak Gahz'rilla'yı çağırır. Grup için tek tokmak yeter. Hinterlands'deki Altar of Zul'un tepesinde duran Qiaga the Keeper (elit) Sacred Mallet'i düşürür: Jintha'Alor'un en tepesindeki sunakta kullanınca Mallet of Zul'Farrak'a dönüşür. İki yer de elitlerle dolu."
L["Opens the gate of the Horde's way into the City of Dalaran; one key opens it for the group. The Image of Archmage Modera gives it with Heart of Disruption: keep that quest in your log until you are inside. The Alliance walks in through the sewer pipe in Cantrips & Crows."] = "Horde'un City of Dalaran'a giden yolundaki kapıyı açar. Tek anahtar kapıyı bütün grup için açar. Anahtarı Image of Archmage Modera, Heart of Disruption göreviyle verir: içeri girene dek bu görevi görev günlüğünde tut. Alliance, Cantrips & Crows'daki kanalizasyon borusundan içeri yürür."
L["Calls up Lyn the Ignored, a hidden boss, at the summoning circle in the City of Dalaran's Underbelly, in the small room past Atrexis the Grave Knight. The Black Tome lies on a table up the stairs behind Archmage Arugal in Shadowfang Keep; use it at the Ambermill Leyline Focus, the blue crystal beside Archmage Ataeric in Ambermill's town hall, and it becomes the Tome of Dalaran."] = "Gizli boss Lyn the Ignored'ı çağırır. Çağırma çemberi City of Dalaran'ın Underbelly kesiminde, Atrexis the Grave Knight'ı geçince gelen küçük odada. Black Tome, Shadowfang Keep'te Archmage Arugal'ın arkasındaki merdivenden çıkınca bir masada durur. Ambermill'in belediye binasında Archmage Ataeric'in yanındaki mavi kristal olan Ambermill Leyline Focus'ta kullanınca Tome of Dalaran olur."
L["Opens a portal from the first khan's spot in Maraudon's outer caves to Earth Song Falls in inner Maraudon; the group walks through it. Celebras the Redeemed makes it once Celebras the Cursed is dead inside."] = "Maraudon'un dış mağaralarında ilk khan'ın yerinden iç Maraudon'daki Earth Song Falls'a bir portal açar. Grup içinden yürüyerek geçer. Celebras the Cursed içeride ölünce portalı Celebras the Redeemed açar."
L["Opens the way into the upper area of Krol'dok Stronghold. Tunk, by the smithy near War Handler Ashka, drops the Krol'dok Moulding; Alphonse Dumas in Farholde Keep forges the key from it with 4 Thick Leather and 12 Iron Bars."] = "Krol'dok Stronghold'un üst kesimine giden yolu açar. Tunk (War Handler Ashka yakınındaki demirhanenin yanında) Krol'dok Moulding düşürür. Farholde Keep'teki Alphonse Dumas bundan 4 Thick Leather ve 12 Iron Bar ile anahtarı döver."
L["Opens the way into the upper area of Krol'dok Stronghold. Tunk, by the smithy near War Handler Ashka, drops the Krol'dok Moulding; Kreza Darkthorn in Rog'mar forges the key from it with 4 Thick Leather and 12 Iron Bars."] = "Krol'dok Stronghold'un üst kesimine giden yolu açar. Tunk (War Handler Ashka yakınındaki demirhanenin yanında) Krol'dok Moulding düşürür. Rog'mar'daki Kreza Darkthorn bundan 4 Thick Leather ve 12 Iron Bar ile anahtarı döver."
L["Use %s beside %s: it becomes %s."] = "%s eşyasını %s yanında kullan: %s olur."
L["Keep %s in your quest log until you are inside: taking it gives you %s, and dropping the quest takes it back."] = "İçeri girene dek %s görevini görev günlüğünde tut: görevi alınca %s sende olur, görevi bırakınca geri alınır."
L["Not open on Forever yet: the attunement is ready for when it opens."] = "Forever'da henüz açık değil. Açıldığında attunement'ın hazır olur."

-- Nav/Handoff.lua
L["Hand guiding to Shortest Path Forever"] = "Yol göstermeyi Shortest Path Forever'a bırak"
L["Shortest Path Forever's arrow, route and journey take you to each goal. Polestar's arrow, route lines, journey steps, travel button, transport alerts, map clicks and /way step aside; the guide window and map pins stay. Off: Polestar guides, and steps aside only while a journey you started in Shortest Path Forever runs."] = "Shortest Path Forever'ın oku, rotası ve yolculuğu seni her hedefe götürür. Polestar'ın oku, rota çizgileri, yolculuk adımları, yolculuk düğmesi, ulaşım uyarıları, harita tıklamaları ve /way devreden çıkar. Rehber penceresi ve harita iğneleri kalır. Kapalı: Polestar yol gösterir, yalnızca Shortest Path Forever'da başlattığın bir yolculuk sürerken çekilir."

