-- Core/Data.lua
L["Polestar no longer uses the old folders Polestar_Guides_<language> and Polestar_Names_<language> (%s): Polestar_<language> holds both now. Close the game and delete them from Interface/AddOns."] = "Polestar artık eski Polestar_Guides_<language> ve Polestar_Names_<language> klasörlerini kullanmıyor (%s): ikisi de artık Polestar_<language> içinde. Oyunu kapat ve onları Interface/AddOns klasöründen sil."
L["Polestar no longer uses its %d walking map folders named Polestar_Nav_R (Polestar_Nav_R0_6_6 and the like): Polestar_Nav_EK and Polestar_Nav_Kalimdor hold those maps now. Close the game and delete the Polestar_Nav_R folders from Interface/AddOns."] = "Polestar, Polestar_Nav_R adlı %d yürüme haritası klasörünü artık kullanmıyor (Polestar_Nav_R0_6_6 gibi): o haritalar şimdi Polestar_Nav_EK ve Polestar_Nav_Kalimdor içinde. Oyunu kapatıp Polestar_Nav_R klasörlerini Interface/AddOns içinden sil."
L["Your install is mixed or incomplete (%s). Close the game, delete every Polestar folder in Interface/AddOns and install Polestar again: with the Polestar Client, the CurseForge app, or the latest zip from GitHub Releases (not \"Source code\")."] = "Kurulumun karışık ya da eksik (%s). Oyunu kapat, Interface/AddOns içindeki tüm Polestar klasörlerini sil ve Polestar'ı yeniden kur: Polestar Client ile, CurseForge uygulamasıyla ya da GitHub Releases'teki en son zip ile (“Source code” değil)."
L["Polestar no longer uses these folders (%s): since 0.4.3 they are inside Polestar, Polestar_Guides_Alliance, Polestar_Guides_Horde and Polestar_Skins. Close the game and delete them from Interface/AddOns."] = "Polestar bu klasörleri artık kullanmıyor (%s): 0.4.3'ten beri Polestar, Polestar_Guides_Alliance, Polestar_Guides_Horde ve Polestar_Skins içindeler. Oyunu kapatıp bunları Interface/AddOns klasöründen sil."

