L["Another character named %s was saved before Forever's client stopped giving addons the realm name. Polestar can't tell whether it is this one, so it stays listed as it was; forget it if it is."] = "%s adlı başka bir karakter, Forever istemcisi eklentilere realm adını vermeyi bırakmadan önce kaydedildi. Polestar bu kaydın bu karaktere ait olup olmadığını anlayamıyor, bu yüzden listede eskisi gibi kalıyor. Bu karakterse unut."
L["%d characters named %s were saved on different realms before Forever's client stopped giving addons the realm name. Polestar can't tell which one you are playing, so they stay listed as they were and this character has a new entry; forget the old one that was this character."] = "%2$s adlı %1$d karakter, Forever istemcisi eklentilere realm adını vermeyi bırakmadan önce farklı realm'lerde kaydedildi. Polestar hangisini oynadığını anlayamıyor, bu yüzden listede eskisi gibi kalıyorlar ve bu karakter için yeni bir kayıt açıldı. Bu karaktere ait eski kaydı unut."
L["Rares met on %d realms are kept apart: Forever's client no longer gives addons the realm name, so Polestar can't tell which of them this is. Rares lists what you meet from now on."] = "%d realm'de karşılaşılan rare'ler ayrı tutuluyor: Forever istemcisi eklentilere artık realm adını vermiyor, bu yüzden Polestar bunun hangisi olduğunu anlayamıyor. Rare'ler sayfası bundan sonra karşılaştıklarını listeler."
L["Characters is turned off. Turn it on under Settings > Discovery > Lookup."] = "Karakterler kapalı. Ayarlar > Keşif > Arama altında aç."

