L["The route doesn't need these: it never hands them in, or they give no XP any more. Abandon asks in the game's own window first."] = "Rotanın bunlara ihtiyacı yok: onları hiç teslim etmiyor ya da artık XP vermiyorlar. “Bırak” önce oyunun kendi penceresinde sorar."
L["Lists the quests in your log the route doesn't need: those it never hands in, and grey ones that give no XP any more. Each has an Abandon button that asks first. The guide window's menu has it too while there are any."] = "Görev günlüğündeki, rotanın gerektirmediği görevleri listeler: hiç teslim etmediklerini ve artık XP vermeyen gri olanları. Her birinde önce soran bir “Bırak” düğmesi var. Böyle görevler varken rehber penceresinin menüsünde de bulunur."
