L["Finished, and the route ahead never hands these in: here is who takes each. Guide me leads you to them, nearest first. A grey one gives almost no XP any more: abandon it if you won't pass by."] = "Bitti ve ilerideki rota bunları hiç teslim etmiyor: işte her birini kimin aldığı. Bana yol göster, seni en yakından başlayarak onlara götürür. Gri olan artık neredeyse hiç XP vermez: yanından geçmeyeceksen bırak."
