L["Every quest in your log is part of your route."] = "Günlüğündeki her görev rotanın parçası."
L["No guide of your route takes, works or hands these in. Keep the ones you want; Abandon asks in the game's own window first."] = "Rotandaki hiçbir rehber bunları almıyor, yapmıyor ya da teslim etmiyor. İstediklerini sakla. Bırak önce oyunun kendi penceresinde sorar."
