L["%s, %s or %s on map and minimap: set in Install or in Settings."] = "Haritada ve mini haritada %s, %s ya da %s: Kurulum'da ya da Ayarlar'da ayarla."
L["Click to open this setting."] = "Bu ayarı açmak için tıkla."
L["Two new zones in your route"] = "Rotanda iki yeni bölge"
L["%s and %s are now part of the 1 to 60 route, for both factions."] = "%s ve %s artık iki taraf için de 1-60 rotasının parçası."
L["Safer, smoother routes"] = "Daha güvenli, daha akıcı rotalar"
L["Every zone reviewed: less walking back, less grinding, fewer mobs well above your level."] = "Her bölge gözden geçirildi: daha az geri yürüme, daha az kasma, seviyenin çok üstünde daha az yaratık."
L["A dungeon instead of a grind"] = "Kasmak yerine bir zindan"
L["Grind steps suggest a dungeon that fits you now, with the game's own level ranges."] = "Kasma adımları, oyunun kendi seviye aralıklarıyla şu an sana uyan bir zindan önerir."
L["Finished quests stay found"] = "Bitmiş görevler kaybolmaz"
L["Handed in where the route passes their NPC; when a guide ends, it says what carries on."] = "Rotanın NPC'lerinin yanından geçtiği yerde teslim edilir, bir rehber bitince neyin sürdüğünü söyler."
L["A new settings window"] = "Yeni bir ayarlar penceresi"
L["Live previews, search that answers questions, Undo, and a short %s for new characters."] = "Canlı önizlemeler, soruları cevaplayan arama, Geri al ve yeni karakterler için kısa bir %s."
L["New and rebuilt skins"] = "Yeni ve yeniden yapılmış görünüm temaları"
L["Nine new skins; %s, %s, %s and %s rebuilt, arrow and all."] = "Dokuz yeni görünüm teması. %s, %s, %s ve %s oku dahil yeniden yapıldı."
L["A target list"] = "Hedef listesi"
L["The target button lists the step's mobs and what they drop; click one to target it."] = "Hedef düğmesi adımın yaratıklarını ve düşürdüklerini listeler, hedef almak için birine tıkla."
L["Small helpers"] = "Küçük yardımcılar"
L["Sell and repair reminders before you leave town; compact mode now has tabs."] = "Kasabadan çıkmadan önce satış ve tamir hatırlatıcıları, kompakt modun artık sekmeleri var."
L["In 9 languages, now with German and Latin American Spanish guides. Thanks, translators!"] = "9 dilde, artık Almanca ve Latin Amerika İspanyolcası rehberlerle. Teşekkürler, çevirmenler!"
L["Caves, cities, flights and more. Found something off? Type %s."] = "Mağaralar, şehirler, uçuşlar vb. Bir tuhaflık mı buldun? %s yaz."
L["A smarter arrow"] = "Daha akıllı ok"
L["Walks that follow your own trail, boats and lifts it understands, flights it remembers, enemy towns it goes round."] = "Senin bıraktığın izi izleyen yürüyüşler, anladığı gemiler ve asansörler, hatırladığı uçuşlar, etrafından dolaştığı düşman kasabaları."
L["Guides named for their zones"] = "Bölgelerine göre adlandırılan rehberler"
L["Titles name the zones you quest in, in walking order. Camping 101 is in for every start-zone profession."] = "Başlıklar görev yaptığın bölgeleri yürüme sırasıyla sayar. Camping 101 her başlangıç bölgesi mesleği için eklendi."
L["Escorts are your choice"] = "Eskortlar senin seçimin"
L["Do it or Skip it, with how long other players' runs take and how often they fail."] = "“Yap” ya da “Atla”, diğer oyuncuların denemelerinin ne kadar sürdüğü ve ne sıklıkla başarısız olduğuyla birlikte."
L["Windows your way"] = "Pencereler senin istediğin gibi"
L["Atlas or Standard layout; Settings and Guides have their own scale; switches for chat messages and the XP line."] = "Atlas ya da Standart düzen. Ayarlar ve Rehberler pencerelerinin ayrı ölçeği var. Sohbet mesajları ve XP satırı için anahtarlar."
L["Every attunement and key for your faction in the guide menu, with a progress bar and %s."] = "Tarafının her attunement'ı ve anahtarı rehber menüsünde, ilerleme çubuğu ve %s ile."
L["Polestar in your language"] = "Polestar senin dilinde"
L["Settings > General > Language shows Polestar in another language than the game's."] = "Ayarlar > Genel > Dil, Polestar'ı oyunun dilinden başka bir dilde gösterir."
L["Fewer folders"] = "Daha az klasör"
L["Quit the game fully and start it again: Polestar is 22 folders now, not 45."] = "Oyundan tamamen çıkıp yeniden başlat: Polestar artık 45 değil, 22 klasör."
L["Steps fixed in dozens of zones. Found something off? Type %s."] = "Onlarca bölgede adımlar düzeltildi. Yanlış bir şey mi buldun? %s yaz."

