L["The dark edge around each number, so it reads on any map."] = "Her numaranın çevresindeki koyu kenar, böylece her haritada okunur."
L["Pulse"] = "Nabız"
L["The glow breathes slowly so the target catches the eye. Still with Reduce motion."] = "Parıltı yavaşça nefes alır, böylece hedef göze çarpar. Hareketi azalt açıkken durgun."
L["Pulse speed"] = "Nabız hızı"
L["Icons"] = "Simgeler"
L["A colour laid over every medallion and the numbered pins' rims. Right-click for none."] = "Her madalyonun ve numaralı iğnelerin kenarlarının üstüne konan bir renk. Hiçbiri için sağ tıkla."
L["The dark disc under the other skins' icons and the rare and death marks. Right-click to go back to the scheme's."] = "Diğer görünüm temalarının simgelerinin ve rare ve ölüm işaretlerinin altındaki koyu disk. Şemanınkine dönmek için sağ tıkla."
L["Scheme"] = "Şema"
L["Spawn areas"] = "Doğma alanları"
L["Area colour"] = "Alan rengi"
L["Every area in one colour. Right-click to go back to each in its own pin's colour."] = "Her alan tek renkte. Her birini kendi iğnesinin rengine döndürmek için sağ tıkla."
L["The pin's colour"] = "İğnenin rengi"
L["Trail dots"] = "İz noktaları"
L["Dot size"] = "Nokta boyutu"
L["Right-click to reset."] = "Sıfırlamak için sağ tıkla."
L["A mark over your arrow at the minimap's centre fades so the arrow shows through it. The game draws the arrow under every addon's marks."] = "Mini haritanın ortasında okunun üstündeki bir işaret solar, böylece ok onun içinden görünür. Oyun oku her eklentinin işaretlerinin altına çizer."
L["Auto"] = "Otomatik"
L["Pins"] = "İğneler"
L["Target pin"] = "Hedef iğnesi"
L["The guide's marks on the world map and the minimap: the target, the numbered steps after it, the areas to search, and every icon."] = "Rehberin dünya haritasındaki ve mini haritadaki işaretleri: hedef, ondan sonraki numaralı adımlar, aranacak alanlar ve her simge."
L["Target size"] = "Hedef boyutu"
L["The pin the arrow points to, on the world map and the minimap. It wears the arrow's colour (Arrow page)."] = "Okun gösterdiği iğne, dünya haritasında ve mini haritada. Okun rengini taşır (Ok sayfası)."
L["Target glow"] = "Hedef parıltısı"
L["The soft halo in the arrow's colour under the target's pin. Its pulse is in the cog."] = "Hedefin iğnesinin altında okun renginde yumuşak hale. Nabzı dişli simgesinde."
L["One breath of the pulse: shorter is faster."] = "Nabzın bir nefesi: kısa olan daha hızlıdır."
L["On the minimap"] = "Mini haritada"
L["The opacity of the soft tint over the places mobs and objects spawn, on the world map and the minimap, their outlines with it. The swatch gives every area one colour."] = "Yaratıkların ve nesnelerin doğduğu yerlerin üstündeki yumuşak tonun opaklığı, dünya haritasında ve mini haritada, çizgileri de onunla birlikte. Renk kutusu her alana tek renk verir."
L["Spawn spots"] = "Doğma noktaları"
L["Small marks on the world map where the target also spawns, each numbered in its tooltip. Click one to search there next."] = "Dünya haritasında hedefin başka doğma yerlerini gösteren küçük işaretler, her biri ipucunda numaralı. Sıradaki aramayı orada yapmak için birine tıkla."
L["Moving dots from you to the target on both maps while route lines are off; the slider is their size. They wear the arrow's colour; their opacity is in the cog."] = "Rota çizgileri kapalıyken iki haritada da senden hedefe hareket eden noktalar. Kaydırıcı boyutlarıdır. Okun rengini taşırlar, opaklıkları dişli simgesinde."
L["The trail's dots on both maps."] = "İzin iki haritadaki noktaları."
L["The numbered pins on the world map and the minimap. Bigger pins also grow past the usual limit on screen. Their rim colour is in the cog."] = "Dünya haritasındaki ve mini haritadaki numaralı iğneler. Büyük iğneler ekranda olağan sınırın ötesine de büyür. Kenar renkleri dişli simgesinde."
L["The accent, a colour for each step ahead so they tell apart, or your own colour (the swatch)."] = "Vurgu, ilerideki her adım için ayırt edilsinler diye bir renk ya da kendi rengin (renk kutusu)."
L["Per step"] = "Adım başına"
L["The numbered pins' colour when Colour is Own colour. Right-click to go back to the accent."] = "Renk, Kendi rengim olduğunda numaralı iğnelerin rengi. Vurguya dönmek için sağ tıkla."
L["The step number on each pin: its size, with the pin's own. The switch shows or hides the numbers, the swatch is their colour, their outline is in the cog."] = "Her iğnedeki adım numarası: boyutu, iğnenin kendisininkiyle birlikte. Anahtar numaraları gösterir ya da gizler, renk kutusu rengidir, dış çizgileri dişli simgesinde."
L["Show numbers"] = "Numaraları göster"
L["The numbers' colour. Right-click to go back to white."] = "Numaraların rengi. Beyaza dönmek için sağ tıkla."
L["How many of the next steps get a pin. Auto: as many as the guide window's Up next shows, else five."] = "Sıradaki adımlardan kaçının iğne aldığı. Otomatik: rehber penceresinin Sıradakiler bölümü kaç gösteriyorsa o kadar, yoksa beş."
L["The pin of the very next step; the later ones fade from here."] = "En yakın sıradaki adımın iğnesi, sonrakiler buradan solar."
L["Fade to"] = "Şuna sol"
L["The farthest step's opacity: the pins fade from Opacity down to this, step by step. The same as Opacity: no fading."] = "En uzak adımın opaklığı: iğneler adım adım Opaklık'tan buna kadar solar. Opaklık ile aynıysa: solma yok."
L["The numbered pins on the minimap, against their size on the world map."] = "Mini haritadaki numaralı iğneler, dünya haritasındaki boyutlarına göre."
L["World map size"] = "Dünya haritası boyutu"
L["Every Polestar mark on the world map, the numbered pins too; they also grow past the usual limit on screen."] = "Dünya haritasındaki her Polestar işareti, numaralı iğneler de, bunlar ekranda olağan sınırın ötesine de büyür."
L["Every Polestar mark on the world map."] = "Dünya haritasındaki her Polestar işareti."
L["Polestar's marks on the minimap; the world map keeps its own."] = "Polestar'ın mini haritadaki işaretleri, dünya haritası kendininkini korur."
L["Every Polestar mark on the minimap."] = "Mini haritadaki her Polestar işareti."
L["Fade over arrow"] = "Okun üstünde sol"
L["Count badge"] = "Sayı rozeti"
L["The small count on a group of services and the ? on an unknown flight master."] = "Bir hizmet grubundaki küçük sayı ve bilinmeyen bir uçuş ustasındaki ?."
L["Medallions"] = "Madalyonlar"
L["Tint"] = "Ton"
L["Large"] = "Büyük"
L["Bigger pins and marks, easier to read and to click."] = "Daha büyük iğneler ve işaretler, okuması ve tıklaması daha kolay."
L["Smaller, fainter pins that leave the map to the map."] = "Haritayı haritaya bırakan daha küçük, daha soluk iğneler."
L["Colour per step"] = "Adım başına renk"
L["Each step ahead in its own colour, none fainter, so the route reads at a glance."] = "İlerideki her adım kendi renginde, hiçbiri daha soluk değil, böylece rota bir bakışta okunur."
L["Icons and target"] = "Simgeler ve hedef"
L["Spawn markers"] = "Doğma işaretleri"
L["Spawn markers for your quests"] = "Görevlerin için doğma işaretleri"
L["A skull on the world map and the minimap at every spawn of the mobs your quests need, one colour per quest and a ring per mob; the things you pick up or use get the pickup bag. Their size and opacity are on the Icons tab."] = "Görevlerinin istediği yaratıkların her doğma yerinde, dünya haritasında ve mini haritada bir kafatası. Her görevin bir rengi, her yaratığın bir halkası var. Toplayacağın ya da kullanacağın şeyler toplama çantası simgesini alır. Boyutları ve opaklıkları Simgeler sekmesinde."
L["Off: the spawn markers show on the world map only."] = "Kapalı: doğma işaretleri yalnız dünya haritasında görünür."
L["Legend on the world map"] = "Dünya haritasında açıklama kutusu"
L["Lists the quests and mobs on the shown map. Hover a row to highlight its markers, click it to turn them off or on."] = "Gösterilen haritadaki görevleri ve yaratıkları listeler. İşaretlerini vurgulamak için bir satırın üstüne gel, kapatıp açmak için tıkla."
L["Only the current step's quests"] = "Yalnız geçerli adımın görevleri"
L["Marks only the quests the guide step you're on works on, not your whole quest log. With no guide running, the whole log shows."] = "Görev günlüğünün tamamını değil, yalnız bulunduğun rehber adımının üzerinde çalıştığı görevleri işaretler. Açık rehber yoksa bütün günlük gösterilir."
L["Quest colours"] = "Görev renkleri"
L["The colours quests are given, in quest-log order: the skull's colour. The first quest keeps the skull's own colours."] = "Görevlere görev günlüğü sırasıyla verilen renkler: kafatasının rengi. İlk görev kafatasının kendi renklerini korur."
L["Mob colours"] = "Yaratık renkleri"
L["The colours of the rings that tell a quest's mobs apart. A quest with one mob has no ring."] = "Bir görevin yaratıklarını birbirinden ayıran halkaların renkleri. Tek yaratıklı görevde halka olmaz."

-- Maps/RouteOptions.lua
L["Theme"] = "Tema"
L["On the world map"] = "Dünya haritasında"
L["The route lines on the world map. Off leaves them on the minimap only."] = "Dünya haritasındaki rota çizgileri. Kapalı onları yalnızca mini haritada bırakır."
L["The dark edge under the line and dots (the line's soft shadow), so they stand out on bright ground. 0% takes it away."] = "Çizginin ve noktaların altındaki koyu kenar (çizginin yumuşak gölgesi), böylece parlak zeminde öne çıkarlar. %0 onu kaldırır."
L["Dashed flights"] = "Kesikli uçuşlar"
L["Flights drawn as a dashed line, so a walk and a flight never read as one. Off: a solid line in the flight's colour."] = "Uçuşlar kesikli bir çizgiyle çizilir, böylece yürüyüş ve uçuş asla tek bir yol gibi okunmaz. Kapalı: uçuşun renginde düz bir çizgi."
L["Direction marks"] = "Yön işaretleri"
L["Small chevrons along the line on the world map pointing the way to the goal."] = "Dünya haritasında çizgi boyunca hedefe giden yolu gösteren küçük oklar."
L["Walk colour"] = "Yürüyüş rengi"
L["The walks' colour: the line, the dots, and route-coloured sparkles. Right-click for the route colour again."] = "Yürüyüşlerin rengi: çizgi, noktalar ve rota renkli ışıltılar. Yeniden rota rengi için sağ tıkla."
L["Flights' colour. Right-click for the theme's."] = "Uçuşların rengi. Temanınki için sağ tıkla."
L["Boats' colour. Right-click for the theme's."] = "Gemilerin rengi. Temanınki için sağ tıkla."
L["Zeppelins' colour. Right-click for the theme's."] = "Zeplinlerin rengi. Temanınki için sağ tıkla."
L["The Deeprun Tram's and lifts' colour. Right-click for the theme's."] = "Deeprun Tram'in ve asansörlerin rengi. Temanınki için sağ tıkla."
L["World map opacity"] = "Dünya haritası opaklığı"
L["Later legs"] = "Sonraki ayaklar"
L["How strongly the legs after this one show, so the way ahead reads first. 0%: only the leg you are on; 100%: as strong as this leg."] = "Önündeki yol önce okunsun diye bundan sonraki ayakların ne kadar belirgin göründüğü. %0: yalnızca üstünde olduğun ayak, %100: bu ayak kadar belirgin."
L["A short stretch of the line stays behind you, fading out. Off: the line starts where you stand."] = "Çizginin kısa bir parçası solarak arkanda kalır. Kapalı: çizgi durduğun yerden başlar."
L["A new goal's route grows from you to the goal over a moment. Never with Reduce motion on."] = "Yeni bir hedefin rotası bir anda senden hedefe doğru uzar. Hareketi azalt açıkken asla."
L["Route on the minimap"] = "Mini haritada rota"
L["How big each of the dots is, on both maps (smaller on continent maps)."] = "Noktaların her birinin ne kadar büyük olduğu, iki haritada da (kıta haritalarında daha küçük)."
L["Dot spacing"] = "Nokta aralığı"
L["How far apart the dots sit along the way."] = "Noktaların yol boyunca ne kadar aralıklı durduğu."
L["Apply"] = "Uygula"
L["How the way to your goal is drawn on the world map and the minimap."] = "Hedefine giden yolun dünya haritasında ve mini haritada nasıl çizildiği."
L["Route"] = "Rota"
L["How strongly the route shows on the world map, line, dots or sparkles; the minimap keeps its own. The switch takes the lines off the world map."] = "Rotanın dünya haritasında ne kadar belirgin göründüğü: çizgi, noktalar ya da ışıltılar, mini harita kendi ayarını korur. Anahtar çizgileri dünya haritasından kaldırır."
L["How strongly the route shows on the minimap, line, dots or sparkles; the world map keeps its own. The switch takes the line off the minimap (the guide pin stays)."] = "Rotanın mini haritada ne kadar belirgin göründüğü: çizgi, noktalar ya da ışıltılar, dünya haritası kendi ayarını korur. Anahtar çizgiyi mini haritadan kaldırır (rehber iğnesi kalır)."
L["The route's line, dots or sparkles on the minimap, each style its own size; the world map keeps its own."] = "Rotanın mini haritadaki çizgisi, noktaları ya da ışıltıları, her stil kendi boyutuyla, dünya haritası kendi ayarını korur."
L["Draw-in"] = "Çizilerek gelme"
L["Route colours tint each leg by how you travel it. Cyan, magenta and white stand apart from the minimap's yellow herb and ore dots and its gold quest marks. A walk colour of your own wins."] = "Rota renkleri her ayağı nasıl gittiğine göre renklendirir. Camgöbeği, macenta ve beyaz, mini haritanın sarı bitki ve maden noktalarından ve altın görev işaretlerinden ayrışır. Kendi yürüyüş rengin önceliklidir."
L["Thickness"] = "Kalınlık"
L["How thick the solid line is on the world map; the minimap's follows it at its own size."] = "Düz çizginin dünya haritasındaki kalınlığı, mini haritadaki onu kendi boyutunda izler."
L["Walked fade"] = "Yürünen kısmın solması"
L["Subtle"] = "Sade"
L["Dazzling"] = "Göz alıcı"
L["Presets"] = "Hazır ayarlar"
L["Subtle: fewer, smaller, calmer sparkles. Default: as they come. Dazzling: many bright sparkles flowing quickly toward the goal. The settings below fine-tune them."] = "İnce: daha az, daha küçük, daha sakin ışıltılar. Varsayılan: geldikleri gibi. Göz kamaştırıcı: hedefe doğru hızla akan çok sayıda parlak ışıltı. Aşağıdaki ayarlar onlara ince ayar yapar."
L["How bright each sparkle and its glow are. The cog holds Subtlety: smaller, dimmer, calmer twinkles."] = "Her ışıltının ve parıltısının ne kadar parlak olduğu. Dişli simgesinde İncelik var: daha küçük, daha sönük, daha sakin pırıltılar."
L["How close together the sparkles sit, the same at any zoom. The cog sets a ceiling on how many show."] = "Işıltıların, her yakınlaştırmada aynı, ne kadar sık durduğu. Dişli simgesi kaç tanesinin görüneceğine bir üst sınır koyar."
L["Most shown"] = "En fazla gösterilen"
L["Flow"] = "Akış"
L["Flights & rides"] = "Uçuşlar ve binişler"
L["Flights"] = "Uçuşlar"
L["Boats"] = "Gemiler"
L["Zeppelins"] = "Zeplinler"
L["Trams & lifts"] = "Tramvaylar ve asansörler"
L["Sparkle subtlety"] = "Işıltı inceliği"

-- QoL/ButtonsOptions.lua
L["Out of combat"] = "Savaş dışında"
L["Scarlet Warrior"] = "Scarlet Warrior"
L["Executor Zygand"] = "Executor Zygand"
L["Launcher & minimap"] = "Başlatıcı ve mini harita"
L["Polestar logo"] = "Polestar logosu"
L["Emblem in the accent"] = "Vurgu renginde amblem"
L["White emblem"] = "Beyaz amblem"
L["Spacing"] = "Aralık"
L["The gap between two buttons of the set."] = "Setin iki düğmesi arasındaki boşluk."
L["Icon inset"] = "Simge iç payı"
L["How far the icon sits in from the button's edge."] = "Simgenin düğmenin kenarından ne kadar içeride durduğu."
L["Panel"] = "Panel"
L["Border"] = "Kenarlık"
L["Right-click to go back to the theme's hairline."] = "Temanın ince çizgisine dönmek için sağ tıkla."
L["How thick the border is, the hover's too."] = "Kenarlığın, üstüne gelindiğindekinin de, ne kadar kalın olduğu."
L["The border under the mouse. Right-click to go back to the accent."] = "Farenin altındaki kenarlık. Vurguya dönmek için sağ tıkla."
L["Name size"] = "Ad boyutu"
L["Automatic outlines the target's name while it shows who it targets, over the game world; the theme's follows your text outline."] = "Otomatik, oyun dünyasının üstünde kimi hedef aldığını gösterirken hedefin adına dış çizgi verir, temanınki yazı dış çizgini izler."
L["The theme's"] = "Temanınki"
L["Thick outline"] = "Kalın dış çizgi"
L["Next names' icons"] = "Sonraki adların simgeleri"
L["The small icons for the names after the next one, under the target's name, and the action badge on a face."] = "Hedefin adının altında, sıradakinden sonraki adlar için küçük simgeler ve bir yüzdeki eylem rozeti."
L["The size of the key binding text, against the theme's."] = "Tuş ataması yazısının boyutu, temanınkine göre."
L["Item count"] = "Eşya sayısı"
L["How many of the item you carry, in the bottom corner."] = "Taşıdığın eşyanın sayısı, alt köşede."
L["Cooldown numbers"] = "Bekleme süresi sayıları"
L["The time left on the item's cooldown, over the sweep. Off hides the game's numbers and those of cooldown addons such as OmniCC."] = "Eşyanın bekleme süresinden kalan zaman, dönen gölgenin üstünde. Kapalı, oyunun sayılarını ve OmniCC gibi bekleme süresi eklentilerininkini gizler."
L["How solid the buttons are outside a fight. Under the mouse they are always solid; at 0% they still work."] = "Düğmelerin savaş dışında ne kadar opak olduğu. Farenin altında her zaman opaktır, %0'da da çalışırlar."
L["How solid the buttons are while you fight."] = "Düğmelerin sen savaşırken ne kadar opak olduğu."
L["Glow when ready"] = "Hazır olunca parılda"
L["Glow colour"] = "Parıltı rengi"
L["Right-click to go back to the accent."] = "Vurguya dönmek için sağ tıkla."
L["Size"] = "Boyut"
L["How solid the floating button is."] = "Yüzen düğmenin ne kadar opak olduğu."
L["Icon"] = "Simge"
L["Button set"] = "Düğme seti"
L["Scale of the quest item, Hearthstone, target and rare buttons. Drag one to move them all. Sizes and layout change once a fight ends."] = "Görev eşyası, Hearthstone, hedef ve rare düğmelerinin ölçeği. Hepsini taşımak için birini sürükle. Boyut ve düzen bir savaş bitince değişir."
L["Direction"] = "Yön"
L["How the set lines up from the quest item button: a column (Hearthstone above, target below) or a row either way. In a row, names read best above or below."] = "Setin görev eşyası düğmesinden nasıl dizildiği: bir sütun (Hearthstone üstte, hedef altta) ya da iki yönden birinde bir satır. Satırda adlar en iyi üstte ya da altta okunur."
L["Target list upward"] = "Hedef listesi yukarı doğru"
L["The target list's names go up from the target button instead of down, for buttons near the bottom of the screen."] = "Hedef listesindeki adlar hedef düğmesinden aşağı değil yukarı doğru dizilir. Ekranın altına yakın düğmeler için."
L["Column"] = "Sütun"
L["Row"] = "Satır"
L["Row, reversed"] = "Satır, ters"
L["Put the buttons back in their default spot. Drag any of them to move the set."] = "Düğmeleri varsayılan yerlerine geri koy. Seti taşımak için herhangi birini sürükle."
L["Quest item"] = "Görev eşyası"
L["The quest item button's size, before the scale. The switch beside it shows or hides the button."] = "Görev eşyası düğmesinin ölçekten önceki boyutu. Yanındaki anahtar düğmeyi gösterir ya da gizler."
L["The Hearthstone button's size, before the scale. The switch beside it shows or hides the button."] = "Hearthstone düğmesinin ölçekten önceki boyutu. Yanındaki anahtar düğmeyi gösterir ya da gizler."
L["The target button's size, before the scale. The switch beside it shows or hides the button."] = "Hedef düğmesinin ölçekten önceki boyutu. Yanındaki anahtar düğmeyi gösterir ya da gizler."
L["The rare button's size, before the scale. The switch beside it shows or hides the button."] = "Rare düğmesinin ölçekten önceki boyutu. Yanındaki anahtar düğmeyi gösterir ya da gizler."
L["Bag"] = "Çanta"
L["The bag space button's size (the cheapest junk, when your bags are nearly full), before the scale."] = "Çanta yeri düğmesinin (çantaların neredeyse doluyken en ucuz çöp) ölçekten önceki boyutu."
L["Plate"] = "Levha"
L["The plate behind each icon: the panel colour, a darker one, or none (the icon alone). The swatch sets your own colour and opacity."] = "Her simgenin arkasındaki levha: panel rengi, daha koyu biri ya da hiçbiri (yalnızca simge). Renk kutusu kendi rengini ve opaklığını ayarlar."
L["Your own colour and opacity for the plate. Right-click to go back to the background's."] = "Levha için kendi rengin ve opaklığın. Arka planınkine dönmek için sağ tıkla."
L["The hairline round each button. Under the mouse it lights up either way. The swatch sets its colour, the cog its thickness."] = "Her düğmenin çevresindeki ince çizgi. Farenin altında her durumda yanar. Renk kutusu rengini, dişli simgesi kalınlığını ayarlar."
L["Hover"] = "Üstüne gelince"
L["A glow round the quest item or Hearthstone button while it can be used now (in range, off cooldown), and round the rare button while a rare is up. It breathes unless Reduce motion is on. The swatch sets its colour."] = "Görev eşyası ya da Hearthstone düğmesi şu an kullanılabilirken (menzilde, bekleme süresi bitmiş) çevresinde, bir rare ortadayken de rare düğmesinin çevresinde bir parıltı. Hareketi azalt açık değilse nefes alır. Renk kutusu rengini ayarlar."
L["Name position"] = "Ad konumu"
L["The size of the names beside the target and rare buttons, against the theme's. The cog sets their outline."] = "Hedef ve rare düğmelerinin yanındaki adların boyutu, temanınkine göre. Dişli simgesi dış çizgilerini ayarlar."
L["Who it targets"] = "Kimi hedef aldığı"
L["Key binding"] = "Tuş ataması"
L["The key a button is bound to, in its top corner. The cog sets its size."] = "Bir düğmenin atandığı tuş, üst köşesinde. Dişli simgesi boyutunu ayarlar."
L["Floating & minimap"] = "Yüzen ve mini harita"
L["The floating button's mark: Polestar's logo, or its emblem alone in your accent colour or in white."] = "Yüzen düğmenin işareti: Polestar'ın logosu ya da yalnızca amblemi, vurgu renginde veya beyaz."
L["Disc"] = "Disk"
L["The round plate behind the floating button's icon. Off, the icon stands alone."] = "Yüzen düğmenin simgesinin arkasındaki yuvarlak levha. Kapalıyken simge tek başına durur."
L["The minimap button's size. The switch beside it shows it on the edge of the minimap. A minimap addon that gathers buttons may size it its own way."] = "Mini harita düğmesinin boyutu. Yanındaki anahtar onu mini haritanın kenarında gösterir. Düğmeleri toplayan bir mini harita eklentisi onu kendi bildiği gibi boyutlandırabilir."
L["Minimap icon"] = "Mini harita simgesi"
L["The minimap button's mark: Polestar's logo, or its emblem alone in your accent colour or in white."] = "Mini harita düğmesinin işareti: Polestar'ın logosu ya da yalnızca amblemi, vurgu renginde veya beyaz."
L["Bigger buttons with bigger names and key bindings."] = "Daha büyük adlar ve tuş atamalarıyla daha büyük düğmeler."
L["The buttons side by side, their names below them."] = "Düğmeler yan yana, adları altlarında."
L["Quiet"] = "Sakin"
L["Half seen out of combat, no glow and no background plate."] = "Savaş dışında yarı görünür, parıltı ve arka levha yok."
L["The quest item, Hearthstone, target and rare buttons, the travel button under the arrow, the floating button and the minimap button."] = "Görev eşyası, Hearthstone, hedef ve rare düğmeleri, okun altındaki yolculuk düğmesi, yüzen düğme ve mini harita düğmesi."
L["The floating button's size. The switch beside it shows it: a small Polestar button you can put anywhere on the screen. Click to hide or show Polestar, right-click for a menu, drag to move it."] = "Yüzen düğmenin boyutu. Yanındaki anahtar onu gösterir: ekranın istediğin yerine koyabileceğin küçük bir Polestar düğmesi. Polestar'ı gizlemek ya da göstermek için tıkla, menü için sağ tıkla, taşımak için sürükle."

