L["Who uses this profile: this character, a class (Whole class) or the whole account (every character without a profile of its own or its class's). Another character's own choice shows on that character."] = "Bu profili kimin kullandığı: bu karakter, bir sınıf (Tüm sınıf) ya da tüm hesap (kendine ya da sınıfına ait profili olmayan her karakter). Başka bir karakterin kendi seçimi o karakterde görünür."
