L["A line of text holding the parts ticked above, from the profile chosen, to paste anywhere."] = "Seçilen profilden, yukarıda işaretli parçaları tutan, istediğin yere yapıştırabileceğin bir satır metin."
L["A new profile with the string's settings in the parts ticked, every other setting at its default. Polestar switches to it."] = "Metnin ayarlarını işaretli parçalarda alan, diğer her ayarı varsayılanında olan yeni bir profil. Polestar ona geçer."
L["The string's settings in the parts ticked into the profile in use; everything else stays as it is. Asks first."] = "Metnin işaretli parçalardaki ayarları kullanılan profile, diğer her şey olduğu gibi kalır. Önce sorar."
L["Puts back what that import changed."] = "O içe aktarmanın değiştirdiklerini geri koyar."
L["At defaults"] = "Varsayılanlarda"
L["Every setting here is at its default, so taking this part puts the defaults back."] = "Buradaki her ayar varsayılanında, bu yüzden bu parçayı almak varsayılanları geri koyar."
L["Window positions stay out unless you tick them: on another screen, frames you dragged can land in odd places."] = "Pencere konumları sen işaretlemedikçe dışarıda kalır: başka bir ekranda sürüklediğin çerçeveler tuhaf yerlere düşebilir."
L["No settings in it: the parts ticked are at their defaults, so taking it puts the defaults back."] = "İçinde ayar yok: işaretli parçalar varsayılanlarında, bu yüzden almak varsayılanları geri koyar."
L["Tick the parts to share and pick the profile, then make the string."] = "Paylaşılacak parçaları işaretle ve profili seç, sonra metni oluştur."
L["1 change"] = "1 değişiklik"
L["%d changes"] = "%d değişiklik"
