-- UI/Looks/GuideWindow.lua
L["Marshal Dughan"] = "Marshal Dughan"
L["Kobolds drop Gold Dust too: keep what you loot on the way."] = "Kobold'lar da Gold Dust düşürür: yolda lootladığını sakla."
