L["With Transparent, how the text stands out from the world: a thin outline, a thick one, or the drop shadow alone."] = "Şeffaf seçiliyken yazının dünyadan nasıl ayrıştığı: ince bir dış çizgi, kalın bir dış çizgi ya da yalnızca gölge."
L["Shadow only"] = "Yalnızca gölge"
