L["Every window's"] = "Her pencereninki"
L["Dividers"] = "Ayırıcılar"
L["The thin lines between the tabs, the step bar and the window's sections."] = "Sekmeler, adım çubuğu ve pencerenin bölümleri arasındaki ince çizgiler."
L["The window fades to this while the cursor is away from it, and comes back in full when you point at it. 100% keeps it as it is."] = "İmleç pencereden uzaktayken pencere buna kadar solar, üstüne gelince tamamen geri gelir. %100 olduğu gibi tutar."
