L["The name of the person to talk to now, or the step's place, at the top of the card."] = "Şimdi konuşulacak kişinin adı ya da adımın yeri, kartın üstünde."
L["The goal lines of the step and of While you're here."] = "Adımın ve Hazır buradayken'in hedef satırları."
