L["Soft strength"] = "Yumuşak gücü"
L["How dark the light shade behind each line of the transparent window is."] = "Şeffaf pencerenin her satırının arkasındaki açık gölgenin ne kadar koyu olduğu."
L["Keep bars shown"] = "Çubukları gösterili tut"
L["The whole guide window, text and all."] = "Tüm rehber penceresi, yazısıyla birlikte."
