L["Compact"] = "Kompakt"
L["This window's own background opacity: how much of the world shows through. Its own colour is the swatch. Unset, both follow every Polestar window's."] = "Bu pencerenin kendi arka plan opaklığı: dünyanın ne kadarının içinden göründüğü. Kendi rengi renk kutusudur. Ayarlanmamışsa ikisi de her Polestar penceresininkini izler."
