L["The whole guide window, text included."] = "Tüm rehber penceresi, yazı dahil."
L["The line around this window, while every window has one. Its colour and thickness, and whether windows have one, are on the Theme page."] = "Her pencerede bir tane varken bu pencerenin çevresindeki çizgi. Rengi ve kalınlığı, pencerelerde olup olmadığı Tema sayfasında."
L["Behaviour"] = "Davranış"
