L["Fold done goals"] = "Bitmiş hedefleri katla"
L["Bars"] = "Çubuklar"
L["Bar text"] = "Çubuk yazısı"
L["Report"] = "Bildir"
L["Goal size"] = "Hedef boyutu"
L["The icons before the person and each goal: talk, kill, collect, the check of a goal done."] = "Kişinin ve her hedefin önündeki simgeler: konuş, öldür, topla, bitmiş bir hedefin onay işareti."
L["The bar at the left edge of the goal or person the arrow points to: its width."] = "Okun gösterdiği hedefin ya da kişinin sol kenarındaki çubuk: genişliği."
L["Its own colour; unset, the accent."] = "Kendi rengi, ayarlanmamışsa vurgu."
L["Tip size"] = "İpucu boyutu"
