L["Up next size"] = "Sıradaki boyutu"
L["Up next and Along the way: their rows and their headers; the rows grow with the text."] = "Sıradaki ve Yol üstünde: satırları ve başlıkları, satırlar yazıyla büyür."
L["The guide's progress at the bottom of the window: its thickness. The game's looks keep their own bar."] = "Rehberin ilerlemesi, pencerenin altında: kalınlığı. Oyunun görünümleri kendi çubuklarını korur."
L["Only the header and the step's goals, narrower and closer together."] = "Yalnızca başlık ve adımın hedefleri, daha dar ve birbirine daha yakın."
L["No background or border: outlined text over the world, a soft shade behind each line."] = "Arka plan ya da kenarlık yok: dünyanın üstünde dış çizgili yazı, her satırın arkasında yumuşak bir gölge."
L["Large text"] = "Büyük yazı"
