L["Tab style"] = "Sekme stili"
L["How the tabs of the open guides show: a strip above the step bar, a menu on the guide's title, small tabs on the window's top edge, or a column down its left side. Default follows the layout."] = "Açık rehberlerin sekmelerinin görünüşü: adım çubuğunun üstünde bir şerit, rehberin başlığında bir menü, pencerenin üst kenarında küçük sekmeler ya da sol kenarı boyunca bir sütun. Varsayılan, düzene uyar."
L["Above the step bar"] = "Adım çubuğunun üstünde"
L["Title menu"] = "Başlık menüsü"
L["On the top edge"] = "Üst kenarda"
L["Down the left side"] = "Sol kenar boyunca"
L["Default (%s)"] = "Varsayılan (%s)"
L["A button in the step bar that opens every step of the guide in one list. The step number and the guide menu open it too."] = "Adım çubuğunda, rehberin bütün adımlarını tek listede açan bir düğme. Adım numarası ve rehber menüsü de bunu açar."
L["Steps before"] = "Önceki adımlar"
L["How many of the steps before this one show over it, one dimmed line each, done or skipped; 0 turns them off. Click one to go back to it."] = "Bundan önceki adımlardan kaçının üstte görüneceği: yapılmış ya da atlanmış, her biri soluk bir satır. 0 kapatır. Geri dönmek için birine tıkla."
L["Journey style"] = "Yolculuk stili"
L["Polestar's layout draws the Journey under the step. Pick a layout with more Journey styles, such as Atlas, in Presets."] = "Polestar düzeninde Yolculuk adımın altında çizilir. Daha fazla Yolculuk stili olan bir düzeni, örneğin Atlas'ı, Hazır ayarlar'dan seç."
L["Where the travel route shows while you travel: under the step, in a card under the window, folded to the leg you are on, as nodes on the timeline, or as chips in the window's foot."] = "Yolculuk sırasında rotanın nerede görüneceği: adımın altında, pencerenin altında bir kartta, bulunduğun ayağa katlanmış, zaman çizelgesinde düğümler olarak ya da pencerenin alt kısmında çipler olarak."
L["Under the step"] = "Adımın altında"
L["Under the window"] = "Pencerenin altında"
L["Under the window, folded"] = "Pencerenin altında, katlanmış"
L["On the timeline"] = "Zaman çizelgesinde"
L["In the foot"] = "Alt kısımda"
L["Window height"] = "Pencere yüksekliği"
L["Fixed: the window is always the height below; drag its grip to resize it like any window. Follows the step: it grows with the step up to that height. Automatic: it grows into all the free room on screen."] = "Sabit: pencere hep aşağıdaki yükseklikte olur, her pencere gibi tutamacını sürükleyerek boyutlandır. Adıma uyar: adımla birlikte o yüksekliğe kadar büyür. Otomatik: ekrandaki bütün boş alana yayılır."
L["Fixed"] = "Sabit"
L["Follows the step"] = "Adıma uyar"
L["Height"] = "Yükseklik"
L["In pixels and as a share of the screen: click the number to type the pixels, or drag the grip at the window's corner. Changing it under Automatic switches to Fixed. A longer step scrolls."] = "Piksel olarak ve ekranın payı olarak: pikseli yazmak için sayıya tıkla ya da pencerenin köşesindeki tutamacı sürükle. Otomatik seçiliyken değiştirirsen Sabit'e geçer. Daha uzun bir adım kaydırılır."
L["With a Fixed height: right under the last goal, the free room past it (above the goals with Grow upward), or on the window's edge."] = "Sabit yükseklikte: son hedefin hemen altında, ondan sonraki boş alanda (“Yukarı doğru büyü” ile hedeflerin üstünde) ya da pencerenin kenarında."
L["Under the last goal"] = "Son hedefin altında"
L["On the window's edge"] = "Pencerenin kenarında"
L["Rows under the step for quests you still have to finish or hand in off the route: ones a guide update left behind you, and finished quests no guide ahead takes in. Off, the guide window's menu still lists the finished ones under Hand in finished quests."] = "Rota dışında bitirmen ya da teslim etmen gereken görevler için adımın altındaki satırlar: rehber güncellemesinin geride bıraktıkları ve ilerideki hiçbir rehberin teslim almadığı bitmiş görevler. Kapalıyken de rehber penceresinin menüsü bitmiş olanları “Biten görevleri teslim et” altında listeler."
L["XP line"] = "XP satırı"
L["The line under the steps: XP per hour, time to level and your pace. Boosted Rest keeps its own line."] = "Adımların altındaki satır: saatte XP, seviye atlamaya kalan süre ve hızın. Boosted Rest'in ayrı satırı var."

