L["The card for a class quest or a dungeon that opened up stays on the guide window until you answer it; set a time and it goes by itself, as Later does."] = "Açılan bir sınıf görevi ya da zindan için kart, sen cevap verene kadar rehber penceresinde kalır, bir süre ayarlarsan Sonra'daki gibi kendiliğinden gider."
