L["Its background's opacity against every Polestar window's (Theme), and its own colour (the swatch). 0 leaves the text on the world."] = "Arka planının opaklığı, her Polestar penceresininkine göre (Tema) ve kendi rengi (renk kutusu). 0 yazıyı dünyanın üstünde bırakır."
L["Its own background colour; the theme's when reset."] = "Kendi arka plan rengi, sıfırlanınca temanınki."
L["Its border's thickness in screen pixels (Theme: the windows' own), and its own colour (the swatch), shown even with the windows' border off."] = "Kenarlığının ekran pikseli olarak kalınlığı (Tema: pencerelerin kendi kenarlığı) ve kendi rengi (renk kutusu), pencerelerin kenarlığı kapalıyken bile gösterilir."
L["A border of its own colour, even with the windows' border off; the theme's when reset."] = "Pencerelerin kenarlığı kapalıyken bile kendi renginde bir kenarlık, sıfırlanınca temanınki."
L["How fast it comes in and goes, against Polestar's own pace."] = "Ne kadar hızlı gelip gittiği, Polestar'ın kendi hızına göre."
L["Card"] = "Kart"
L["Alert in combat"] = "Savaşta uyar"
L["Line up alerts"] = "Uyarıları sırala"
L["The rare alert, the transport banner and While you're here line up one under the other from one place, instead of each at its own place where they can overlap. Which way they grow, the gap and how many: the cog."] = "Rare uyarısı, ulaşım afişi ve Hazır buradayken, her biri üst üste binebilecekleri kendi yerinde durmak yerine tek bir yerden alt alta dizilir. Hangi yöne büyüdükleri, aradaki boşluk ve kaç tane oldukları: dişli simgesinde."
L["Below: the line hangs from its top and grows down. Above: it stands on its bottom and grows up."] = "Alt: sıra üstünden asılır ve aşağı büyür. Üst: altının üstünde durur ve yukarı büyür."
