L["The whole card, a smaller one with no trip or note, or none: the quest's accept is then a row like any other. Full turns compact with the window."] = "Kartın tamamı, yolculuk ve not olmadan daha küçüğü ya da hiçbiri. Hiçbiri seçiliyken görevi alma, diğerleri gibi bir satır olur. Pencere kompakt olunca Tam da kompakt olur."
L["A short chime the first time a class quest chain's card or heads-up shows. Off while the game's sound effects are off."] = "Bir sınıf görevi zincirinin kartı ya da uyarısı ilk kez göründüğünde kısa bir çınlama. Oyunun ses efektleri kapalıyken kapalı."
L["Where the card goes: on the guide window's top edge (under the window when the screen has no room above), under its bottom edge (over it when there is no room below), or on a spot of its own that you move with Move frames."] = "Kartın nereye gittiği: rehber penceresinin üst kenarına (ekranın üstünde yer yoksa pencerenin altına), alt kenarının altına (altta yer yoksa üstüne) ya da Çerçeveleri taşı ile taşıdığın kendi yerine."
