L["The size of the time against Polestar's text size."] = "Sürenin boyutu, Polestar'ın yazı boyutuna göre."
L["Time shows"] = "Gösterilen süre"
L["Time left"] = "Kalan süre"
L["How far along"] = "Ne kadar ilerlendi"
L["Both"] = "İkisi de"
L["Instance tracker"] = "Instance takipçisi"
L["instance tracker"] = "instance takipçisi"
L["Count size"] = "Sayı boyutu"
L["The size of the instance count against Polestar's text size."] = "Instance sayısının boyutu, Polestar'ın yazı boyutuna göre."
L["party panel"] = "grup paneli"
L["The size of the members' names and the panel's title against Polestar's text size."] = "Üyelerin adlarının ve panelin başlığının boyutu, Polestar'ın yazı boyutuna göre."
L["Mark width"] = "İşaret genişliği"
L["Mark colour"] = "İşaret rengi"
L["Show the level"] = "Seviyeyi göster"
L["The guide's level beside the mark (\"Guide: 14 (2 levels)\"). Off: the mark alone."] = "İşaretin yanında rehberin seviyesi (“Rehber: 14 (2 seviye)”). Kapalı: yalnızca işaret."
L["A dark outline round the letters, legible over the bar's art."] = "Harflerin çevresinde koyu bir dış çizgi, çubuğun çizimi üstünde okunur."
L["Steps listed"] = "Listelenen adımlar"
L["How many of the route's steps the journey lists; the rest are counted on one line."] = "Yolculuğun rotanın adımlarından kaçını listelediği, kalanı tek satırda sayılır."
L["The number before each of the journey's steps."] = "Yolculuğun her adımının önündeki numara."
L["Bar"] = "Çubuk"
L["The progress bar along its bottom: the switch shows it, the slider is its thickness, the swatch its colour (the accent when reset)."] = "Altı boyunca ilerleme çubuğu: anahtar onu gösterir, kaydırıcı kalınlığıdır, renk kutusu rengidir (sıfırlanınca vurgu)."
L["The bar's fill; the accent when reset."] = "Çubuğun dolgusu, sıfırlanınca vurgu."
L["Its outline and what the time shows: the cog."] = "Dış çizgisi ve sürenin ne gösterdiği: dişli simgesinde."
L["Its outline: the cog."] = "Dış çizgisi: dişli simgesinde."
L["In instances"] = "Instance'larda"
L["The flight timer, the journey, the instance tracker, the guide's mark on the XP bar and the party panel: their size, look and when they show."] = "Uçuş zamanlayıcısı, yolculuk, instance takipçisi, rehberin XP çubuğundaki işareti ve grup paneli: boyutları, görünüşleri ve ne zaman göründükleri."
L["Instances & XP"] = "Instance'lar ve XP"
L["Level mark"] = "Seviye işareti"
L["Guide level"] = "Rehber seviyesi"
L["How wide the mark on the bar is, and its colour with its label's (the swatch; the accent when reset)."] = "Çubuktaki işaretin ne kadar geniş olduğu ve etiketiyle birlikte rengi (renk kutusu, sıfırlanınca vurgu)."
L["The mark and its label; the accent when reset."] = "İşaret ve etiketi, sıfırlanınca vurgu."
L["Level text"] = "Seviye yazısı"
L["The size of the guide's level beside the mark; its outline: the cog."] = "İşaretin yanındaki rehber seviyesinin boyutu, dış çizgisi: dişli simgesinde."
L["Every tracker smaller, the flight timer without its bar."] = "Her takipçi daha küçük, uçuş zamanlayıcısı çubuksuz."
L["Every tracker bigger, its text with it."] = "Her takipçi daha büyük, yazısı da onunla."
L["The time left (with %s while it is an estimate), how far along the flight is, or both."] = "Kalan süre (tahminken %s ile), uçuşun ne kadar ilerlediği ya da ikisi de."

-- UI/Movers.lua
L["%d, %d"] = "%d, %d"
L["%d × %d"] = "%d × %d"
L["Drag to move it (Shift: along one line). Arrow keys nudge it, Shift for 10 px."] = "Taşımak için sürükle (Shift: tek çizgi boyunca). Ok tuşları onu kaydırır, 10 piksel için Shift."
L["Reset all positions?"] = "Tüm konumlar sıfırlansın mı?"
L["Reset all positions"] = "Tüm konumları sıfırla"
L["Every Polestar frame goes back to its default place."] = "Her Polestar çerçevesi varsayılan yerine döner."
L["Move Polestar's frames"] = "Polestar'ın çerçevelerini taşı"
L["Drag a box. Click one, then nudge it with the arrow keys."] = "Bir kutuyu sürükle. Birine tıkla, sonra ok tuşlarıyla kaydır."
L["Grid"] = "Izgara"
L["Lines to line frames up on; a dragged frame lands on them."] = "Çerçeveleri hizalamak için çizgiler, sürüklenen bir çerçeve onların üstüne oturur."
L["Snap"] = "Yapıştır"
L["Frames line up with the screen's centre and with each other's edges as you drag."] = "Sürüklerken çerçeveler ekranın ortasıyla ve birbirlerinin kenarlarıyla hizalanır."
L["You can't move frames in combat."] = "Savaşta çerçeveleri taşıyamazsın."
L["Move Polestar's frames (again to lock them)"] = "Polestar'ın çerçevelerini taşı (kilitlemek için yine)"
L["Lock Polestar's frames in place"] = "Polestar'ın çerçevelerini yerlerine kilitle"
L["Unlock"] = "Kilidi aç"
L["A box over each of Polestar's frames (the guide window, the arrow, the buttons, the alerts and the trackers) to drag where you want it, with a grid and snapping. Also /polestar unlock."] = "Polestar'ın her çerçevesinin (rehber penceresi, ok, düğmeler, uyarılar ve takipçiler) üstünde, istediğin yere sürüklemek için bir kutu, ızgara ve yapışmayla. Ayrıca /polestar unlock."
L["Snap while moving"] = "Taşırken yapıştır"
L["A dragged frame lines up with the screen's centre and with the other frames' edges and centres."] = "Sürüklenen bir çerçeve ekranın ortasıyla ve diğer çerçevelerin kenarları ve ortalarıyla hizalanır."
L["Lines to line frames up on while they are unlocked; a dragged frame lands on them."] = "Kilitleri açıkken çerçeveleri hizalamak için çizgiler, sürüklenen bir çerçeve onların üstüne oturur."
L["Grid size"] = "Izgara boyutu"
L["How far apart the grid's lines are."] = "Izgara çizgilerinin birbirinden ne kadar uzak olduğu."
L["Right-click: its settings, or back to its default place. Shift-right-click hides the box until you exit."] = "Sağ tık: ayarları ya da varsayılan yerine dönüş. Shift ile sağ tık, çıkana kadar kutuyu gizler."
L["Its settings"] = "Ayarları"
L["Opens the settings on this frame's look; the boxes stay up."] = "Bu çerçevenin görünüşüyle ilgili ayarları açar, kutular açık kalır."
L["Back to its default place."] = "Varsayılan yerine geri."
L["Hide this box"] = "Bu kutuyu gizle"
L["Until you exit, so it can't be moved by mistake. Also Shift-right-click."] = "Yanlışlıkla taşınmasın diye çıkana kadar. Ayrıca Shift ile sağ tık."
L["Move frames: every control"] = "Çerçeveleri taşı: tüm kontroller"
L["Drag a box to move its frame; hold Shift to keep to one line."] = "Çerçevesini taşımak için bir kutuyu sürükle, tek çizgide kalmak için Shift'i basılı tut."
L["Click a box to select it: the arrow keys nudge it 1 px (Shift: 10), and its X and Y can be typed under this bar."] = "Seçmek için bir kutuya tıkla: ok tuşları onu 1 piksel kaydırır (Shift: 10). X ve Y değerleri bu çubuğun altına yazılabilir."
L["Right-click a box: its settings, its default place, or hide it. Shift-right-click hides it until you exit."] = "Bir kutuya sağ tıkla: ayarları, varsayılan yeri ya da gizle. Shift ile sağ tık, çıkana kadar onu gizler."
L["The mouse wheel over boxes on top of each other brings the next one forward."] = "Üst üste binen kutuların üstünde fare tekerleği sıradakini öne getirir."
L["Hold Shift to see through this bar and reach a frame under it."] = "Bu çubuğun içinden görmek ve altındaki bir çerçeveye ulaşmak için Shift'i basılı tut."
L["Escape or Exit to finish (it asks before discarding what moved); Save and exit keeps it."] = "Bitirmek için Escape ya da Çık (taşınanı atmadan önce sorar), Kaydet ve çık onu korur."
L["Show hidden boxes"] = "Gizli kutuları göster"
L["The boxes you hid with Shift-right-click, back."] = "Shift ile sağ tıklayarak gizlediğin kutular geri gelir."
L["Revert"] = "Geri döndür"
L["Every frame back where it stood when you unlocked them."] = "Her çerçeve, kilitlerini açtığın andaki yerine geri."
L["Exit"] = "Çık"
L["Also Escape. When something moved, it asks whether to keep it."] = "Ayrıca Escape. Bir şey taşındıysa korunsun mu diye sorar."
L["Save and exit"] = "Kaydet ve çık"
L["Every frame stays where it is now."] = "Her çerçeve şu an olduğu yerde kalır."
L["X"] = "X"
L["Its centre's distance from the screen's centre, right of it; type one and press Enter."] = "Ortasının ekranın ortasına sağa doğru uzaklığı, bir değer yaz ve Enter'a bas."
L["Y"] = "Y"
L["Its centre's distance from the screen's centre, above it; type one and press Enter."] = "Ortasının ekranın ortasına yukarı doğru uzaklığı, bir değer yaz ve Enter'a bas."
L["Show hidden (%d)"] = "Gizlileri göster (%d)"
L["Moving Polestar's frames"] = "Polestar'ın çerçeveleri taşınıyor"
L["Drag a box to move its frame, or click it and nudge it with the arrow keys. Right-click a box for more. Save and exit keeps what you moved; Exit asks first. The (i) lists every control."] = "Çerçevesini taşımak için bir kutuyu sürükle ya da ona tıklayıp ok tuşlarıyla kaydır. Daha fazlası için bir kutuya sağ tıkla. Kaydet ve çık taşıdıklarını korur, Çık önce sorar. (i) her kontrolü listeler."
L["Unlock mode waits for the fight to end; what you moved is kept."] = "Kilit açık modu savaşın bitmesini bekliyor, taşıdıkların korunur."
L["Discard your changes?"] = "Değişikliklerin atılsın mı?"
L["Discard"] = "At"
L["Keep editing"] = "Düzenlemeye devam et"
L["One frame moved since you unlocked. Discard puts it back where it stood."] = "Kilitleri açtığından beri bir çerçeve taşındı. At, onu durduğu yere geri koyar."
L["%d frames moved since you unlocked. Discard puts them back where they stood."] = "Kilitleri açtığından beri %d çerçeve taşındı. At, onları durdukları yere geri koyar."

