-- Maps/Options.lua
L["Rares, travel & zones"] = "Rare'ler, yolculuk ve bölgeler"
L["Zones and coordinates"] = "Bölgeler ve koordinatlar"
L["Flight arcade"] = "Uçuş oyunları"
L["Game on flights"] = "Uçuşta oyun"
L["None: don't offer a game"] = "Hiçbiri: oyun önerme"
L["On a flight with a minute or more to go, Polestar offers a game to play while you wait: Freedoom Arcade by petllama (three levels of Freedoom, or the whole game when the Freedoom Arcade addon is installed), Sky Jewels by RikyZ90, a match-three game, or Tetris by beemerwt. The card under the flight timer plays the one you pick. 10 seconds before you land, the game is saved, paused and closed. /polestar arcade, /polestar jewels and /polestar tetris open them any time."] = "Bir dakika ya da daha uzun sürecek bir uçuşta Polestar beklerken oynaman için bir oyun önerir: petllama'nın Freedoom Arcade oyunu (Freedoom'dan üç bölüm, Freedoom Arcade eklentisi kuruluysa oyunun tamamı), üçlü eşleştirme oyunu Sky Jewels (RikyZ90) ya da Tetris (beemerwt). Uçuş sayacının altındaki kart seçtiğini oynatır. İnişe 10 saniye kala oyun kaydedilir, duraklatılır ve kapanır. /polestar arcade, /polestar jewels ve /polestar tetris bunları istediğin zaman açar."

-- Dungeons/Options.lua
L["As for all dungeons"] = "Tüm zindanlardaki gibi"
L["Run it: the leveling guide picks up its quests on the way and takes you to the door. Skip it: the guide keeps to the solo route. As for all dungeons: Guide, Automation, Dungeons in my route answers."] = "Gir: seviye rehberi yolda görevlerini alır ve seni kapıya götürür. Atla: rehber tek başına rotaya bağlı kalır. Tüm zindanlar için geçerli olan: Rehber, Otomasyon, Rotamdaki zindanlar ayarı."
L["Off: the guide skips this group quest and keeps to the solo route. Until you choose, Guide, Automation, Group quests answers for it; by default the guide asks when it gets there."] = "Kapalı: rehber bu grup görevini atlar ve tek başına rotada kalır. Seçimini yapana kadar Rehber, Otomasyon, Grup görevleri ayarı geçerli, varsayılan olarak rehber oraya gelince sorar."
L["When a level-up opens a dungeon's quests to this character, a card on the guide window says so, once per dungeon, with a button that picks up its quests in a new tab. On a step that grinds to a level, a line under it names a dungeon at your level and its quests."] = "Bir seviye atlaması bu karaktere bir zindanın görevlerini açtığında, rehber penceresindeki bir kart bunu her zindan için bir kez söyler, zindanın görevlerini yeni bir sekmede toplayan bir düğmeyle. Bir seviyeye kadar kasılan bir adımda, altındaki bir satır seviyene uygun bir zindanı ve görevlerini söyler."

