L["A look in one click: it sets the settings it names and puts the others of these looks back to their defaults. Right-click goes back to the defaults."] = "Tek tıkla bir görünüm: adını verdiği ayarları yapar, bu görünümlerin diğer ayarlarını varsayılanlarına döndürür. Sağ tık varsayılanlara döner."
