-- UI/GuideFrameBanner.lua
L["Kept in your log: %s"] = "Günlüğünde saklandı: %s"
L["If you run it later, the dungeon's page has a hand-in guide for them."] = "Onu sonra koşarsan zindanın sayfasında onlar için bir teslim rehberi var."
L["%s next: start looking for a group."] = "Sıradaki %s: grup aramaya başla."
L["%s in %d steps: start looking for a group."] = "%2$d adım sonra %1$s: grup aramaya başla."
L["Dungeon on your way: %s, for a group of five."] = "Yolundaki zindan: %s, beş kişilik bir grup için."
L["The guide picks up 1 quest for it and runs it in about %d steps."] = "Rehber bu zindan için 1 görev alır, zindana yaklaşık %d adım sonra girer."
L["The guide picks up %d quests for it and runs it in about %d steps."] = "Rehber bu zindan için %d görev alır, zindana yaklaşık %d adım sonra girer."
L["Skip it and the guide keeps to the solo route."] = "Atlarsan rehber tek başına rotaya bağlı kalır."
L["Run it"] = "Gir"
L["%s: a group of five runs it in about an hour."] = "%s: beş kişilik bir grup onu yaklaşık bir saatte koşar."
L["No group? Skip it: the guide goes on with the solo route, and its quests stay in your log."] = "Grup yok mu? Atla: rehber tek başına rotayla devam eder, görevleri günlüğünde kalır."
L["No group? Skip it"] = "Grup yok mu? Atla"
L["1 finished quest here first"] = "Önce burada 1 bitmiş görev"
L["%d finished quests here first"] = "Önce burada %d bitmiş görev"
L["Jump anyway? They stay in your log, and the guide lists who takes each in."] = "Yine de atlansın mı? Günlüğünde kalırlar, rehber her birini kimin aldığını listeler."
L["Jump anyway"] = "Yine de atla"
L["Open any flight master's map once on this continent so Polestar knows your flight paths."] = "Polestar uçuş noktalarını bilsin diye bu kıtada bir uçuş ustasının haritasını bir kez aç."
L["This guide is for %s characters. Polestar won't guide you through it."] = "Bu rehber %s karakterleri için. Polestar sana bunda yol göstermez."
L["Equip it"] = "Tak"
L["Report to Danitha (Garen Largo, the Undercity), then A Paladin's Steed (Danitha Morr, Bandarion Keep): it teaches you to summon your Warhorse."] = "Report to Danitha (Garen Largo, Undercity), ardından A Paladin's Steed (Danitha Morr, Bandarion Keep): Warhorse çağırmayı öğretir."
L["%s (level %d)"] = "%s (seviye %d)"
L["%s takes these once you reach their level: %s"] = "%s bunları seviyelerine gelince alır: %s"
L["Waiting for your level, taken where a later guide passes the giver: %s"] = "Seviyeni bekliyor, sonraki bir rehber görev verenin yanından geçerken alınacak: %s"
L["Looking ahead."] = "İleriye bakıyorsun."
L["Looking back."] = "Geriye bakıyorsun."
L["On the way to your map point (%s)."] = "Harita noktana gidiyorsun (%s)."
L["Some of this guide's quests follow on from %s. Start there for the full set, or carry on here; the guide fills in with nearby quests."] = "Bu rehberin bazı görevleri %s rehberinin devamı. Hepsi için oradan başla ya da burada devam et. Rehber boşlukları yakındaki görevlerle doldurur."
L["You are past this class quest's levels."] = "Bu sınıf görevinin seviyelerini geçtin."
L["Escort: %s"] = "Eskort: %s"
L["Do it"] = "Yap"

-- Core/Pause.lua
L["Press %s to resume, or open the guide window."] = "Devam etmek için %s tuşuna bas ya da rehber penceresini aç."
L["Right-click the minimap button and pick Pause to resume, or open the guide window."] = "Devam etmek için mini harita düğmesine sağ tıklayıp Duraklat'ı seç ya da rehber penceresini aç."
L["Open the guide window to resume."] = "Devam etmek için rehber penceresini aç."
L["Type /polestar resume, or open the guide window."] = "/polestar resume yaz ya da rehber penceresini aç."
L["Polestar is paused: the arrow and the guide window step aside. It resumes by itself when you leave the dungeon alive."] = "Polestar duraklatıldı: ok ve rehber penceresi kenara çekilir. Zindandan sağ çıkınca kendiliğinden devam eder."
L["Polestar is paused"] = "Polestar duraklatıldı"
L["Paused for two hours without a dungeon: Polestar resumed."] = "Zindan olmadan iki saat duraklatıldı: Polestar devam etti."
