-- L["A small Polestar button you can put anywhere on the screen. Click to show or hide the guide, right-click for a menu, drag to move it. It hides with the window in combat and in dungeons when those are set to Hide."] = "Ekranın istediğin yerine koyabileceğin küçük bir Polestar düğmesi. Rehberi göstermek ya da gizlemek için tıkla, menü için sağ tıkla, taşımak için sürükle. Savaşta ve zindanlarda, bunlar Gizlensin olarak ayarlıysa pencereyle birlikte gizlenir."
-- L["When %s comes into sight, a card says so and the rare button targets him and waves. At most once every half hour, never in combat or instances."] = "%s görüş alanına girince bir kart bunu söyler, rare düğmesi de onu hedef alıp el sallar. En fazla yarım saatte bir; savaşta ya da instance'larda asla."
